{
  "interpretation": {
    "name": "TightenLine3WithSharedNutrunner",
    "scope": {"line": 3, "station": "st3", "tool": "NR7", "variant": "F35"},
    "goal": "Use the shared nutrunner NR7 to tighten the fasteners of the F35 forklift variant at station st3 of line 3, then return the tool to the crib.",
    "constraints": [
      "Reserve NR7 exclusively before any use and release it at the end",
      "Transport NR7 to the station before configure-tool and tighten-fasteners",
      "The tightening program comes only from get-program, with no literal torque or tolerance values",
      "The tightening must be evaluated and recorded for traceability",
      "NR7 must be back in the crib at the end",
      "transport-tool is delegated to agvexecutor"
    ],
    "preference": "",
    "priority": "normal",
    "horizon": "One-off request for the current tightening cycle",
    "requested_capabilities": [],
    "omit_services": []
  },
  "recipe": {
    "name": "line3-nutrunner-tightening",
    "first_action": "prepare",
    "actions": [
      {
        "name": "prepare",
        "next": "bring-tool",
        "steps": [
          {"name": "reserve", "service": "reserve-tool", "next": [], "dep": [], "executor": null, "params": {}},
          {"name": "program", "service": "get-program", "next": [], "dep": [], "executor": null, "params": {}}
        ]
      },
      {
        "name": "bring-tool",
        "next": "tighten",
        "steps": [
          {"name": "transport-to-station", "service": "transport-tool", "next": [], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "station"}}
        ]
      },
      {
        "name": "tighten",
        "next": "quality",
        "steps": [
          {"name": "configure", "service": "configure-tool", "next": ["tighten-bolts"], "dep": ["program", "reserve", "transport-to-station"], "executor": null, "params": {}},
          {"name": "tighten-bolts", "service": "tighten-fasteners", "next": [], "dep": ["configure", "reserve", "transport-to-station"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "quality",
        "next": "return-tool",
        "steps": [
          {"name": "evaluate", "service": "evaluate-tightening", "next": [], "dep": ["tighten-bolts", "program"], "executor": null, "params": {}},
          {"name": "record", "service": "record-tightening", "next": [], "dep": ["tighten-bolts"], "executor": null, "params": {}}
        ]
      },
      {
        "name": "return-tool",
        "next": null,
        "steps": [
          {"name": "transport-to-crib", "service": "transport-tool", "next": ["release"], "dep": ["reserve"], "executor": "agvexecutor", "params": {"to": "crib"}},
          {"name": "release", "service": "release-tool", "next": [], "dep": ["reserve", "transport-to-crib"], "executor": null, "params": {}}
        ]
      }
    ]
  }
}
